const results = []
for (const entry of [...corpus, ...probes]) {
  const cleanup = []
  const result = { name: entry.name, query: entry.query }
  try {
    const connection = await start({ after(fn) { cleanup.push(fn) } })
    const local = await runCase(connection, entry)
    if (compare) {
      result.local = local
      result.reference = await isolatedReference(config, connection => runCase(connection, entry))
      result.differences = differences(local, result.reference)
      result.status = !complete(local) || !complete(result.reference) ? 'incomplete' : result.differences.length ? 'different' : 'match'
    } else Object.assign(result, local)
  } catch (error) { result.transportError = error.message; result.status = 'incomplete' }
  finally { for (const fn of cleanup.reverse()) await fn() }
  results.push(result)
  console.log(`${compare ? result.status : result.execution && !result.execution.errors.length ? 'executed' : 'gap'}: ${entry.name}`)
}
await mkdir('artifacts/compatibility', { recursive: true })
const output = `artifacts/compatibility/${compare ? 'comparison' : 'local'}.json`
await writeFile(output, JSON.stringify(canonical({
  mode: compare ? 'sql-server-comparison' : 'local-diagnostic-only',
  reference: 'mirek/mssqlite@7f71f2081602f8e3051998f5c11f058e65fe24ec',
  upstreamCases: corpus.length, additionalProbes: probes.length,
  ...(compare ? { referenceVersion } : {}),
  warning: compare ? 'Matches apply only to captured observations in these cases; this is not proof of full SQL Server compatibility.' : 'Successful execution does not prove SQL Server equivalence. No SQL Server endpoint was compared.', results
}), null, 2))
console.log(`Recorded ${results.length} cases in ${output}.`)
// Preserve diagnostic SQL gaps in local mode, but fail the command when the
// server could not be reached or launched. Capturing transport failures is not
// a successful audit run.
if (results.some(result => result.transportError)
    || (compare && results.some(result => result.status !== 'match'))) process.exitCode = 1
